-- This fragment runs inside the rollback-only v4 fixture, after its synthetic identities are created.
-- Invoke mobile-5-hr-workflows.ps1 with an isolated mobile5_hr_* database.
CREATE FUNCTION pg_temp.v5_deny(d jsonb,code text,label text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 BEGIN PERFORM public.mobile_hr_service_v5(d);
 EXCEPTION WHEN OTHERS THEN IF SQLSTATE=code THEN RAISE NOTICE 'PASS: %',label;RETURN; END IF; RAISE; END;
 RAISE EXCEPTION 'Unexpected allow: %',label;
END $$;
CREATE TEMP TABLE v5(k text PRIMARY KEY,v jsonb);
GRANT ALL ON v5 TO authenticated;
