CREATE FUNCTION pg_temp.reviewed(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE submitted jsonb;
BEGIN
 PERFORM pg_temp.actor(1);
 submitted:=public.mobile_hr_service_v5(jsonb_build_object('op','serviceSubmit','operationId',gen_random_uuid(),'employeeId',998810,'proposal',p));
 PERFORM pg_temp.actor(2);
 RETURN public.mobile_hr_service_v5(jsonb_build_object('op','serviceDecision','operationId',gen_random_uuid(),'employeeId',998810,'id',submitted->'id','revision','1','decision','approve','reason',''));
END $$;
CREATE FUNCTION pg_temp.fulfil(r jsonb,cmd jsonb) RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('op','serviceFulfil','id',r->'id','employeeId',998810,'revision','2','operationId',gen_random_uuid(),'command',cmd)
$$;
SET LOCAL ROLE authenticated;
